using System.Collections.Generic;
using UnityEngine;

// Creates and plays all of the game's audio. Every sound is generated by code,
// so there are no audio files to import. It builds itself when the game starts,
// so nothing needs to be added to the scene.
public class SoundManager : MonoBehaviour
{
    public enum Sfx
    {
        Jump,
        Slide,
        Lane,
        Coin,
        PowerUp,
        Hit,
        ShieldBreak,
        GameOver,
        Click
    }

    public static SoundManager Instance { get; private set; }

    private enum Wave
    {
        Sine,
        Triangle,
        Square
    }

    private const int SampleRate = 22050;

    // Music loudness in each part of the game (0 to 1)
    private const float MusicMenuVolume = 0.18f;
    private const float MusicPlayVolume = 0.28f;
    private const float MusicGameOverVolume = 0.06f;

    private static readonly System.Random noiseGenerator = new System.Random(1234);

    private readonly Dictionary<Sfx, AudioClip> clips = new Dictionary<Sfx, AudioClip>();
    private readonly Dictionary<Sfx, float> volumes = new Dictionary<Sfx, float>();

    private AudioSource musicSource;
    private AudioSource sfxSource;
    private AudioSource coinSource;

    private bool muted;
    private float coinPitch = 1f;
    private float lastCoinTime;

    // What the manager saw last frame, used to detect events
    private GameManager lastManager;
    private GameState previousState;
    private bool previousStumbled;
    private bool previousShield;

    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]
    private static void AutoCreate()
    {
        if (Instance != null) return;

        GameObject host = new GameObject("SoundManager");
        host.AddComponent<SoundManager>();
    }

    public static void Play(Sfx sfx)
    {
        if (Instance != null) Instance.PlayInternal(sfx);
    }

    void Awake()
    {
        if (Instance != null && Instance != this)
        {
            Destroy(gameObject);
            return;
        }

        Instance = this;
        DontDestroyOnLoad(gameObject);

        muted = PlayerPrefs.GetInt("Muted", 0) == 1;
        ApplyMute();

        musicSource = CreateSource(true);
        sfxSource = CreateSource(false);
        coinSource = CreateSource(false);

        BuildSounds();

        musicSource.clip = BuildMusic();
        musicSource.volume = MusicMenuVolume;
        musicSource.Play();
    }

    void Update()
    {
        GameManager gm = GameManager.Instance;
        float targetMusic = MusicMenuVolume;

        if (gm != null)
        {
            if (gm != lastManager)
            {
                // A new scene or run: note where things stand without making any sound
                lastManager = gm;
                previousState = gm.State;
                previousStumbled = gm.IsStumbled;
                previousShield = gm.ShieldActive;
            }

            DetectEvents(gm);

            if (gm.State == GameState.Playing) targetMusic = MusicPlayVolume;
            else if (gm.State == GameState.GameOver) targetMusic = MusicGameOverVolume;
        }

        musicSource.volume = Mathf.MoveTowards(musicSource.volume, targetMusic, Time.unscaledDeltaTime * 0.4f);

        if (coinPitch > 1f && Time.time - lastCoinTime > 0.7f) coinPitch = 1f;
    }

    private void DetectEvents(GameManager gm)
    {
        GameState state = gm.State;

        if (state != previousState)
        {
            if (state == GameState.GameOver) PlayInternal(Sfx.GameOver);
            else PlayInternal(Sfx.Click);

            previousState = state;
        }

        if (gm.IsStumbled && !previousStumbled && state == GameState.Playing)
        {
            PlayInternal(Sfx.Hit);
        }
        previousStumbled = gm.IsStumbled;

        if (previousShield && !gm.ShieldActive && gm.IsInvulnerable)
        {
            PlayInternal(Sfx.ShieldBreak);
        }
        previousShield = gm.ShieldActive;
    }

    private void PlayInternal(Sfx sfx)
    {
        AudioClip clip;
        if (!clips.TryGetValue(sfx, out clip)) return;

        float volume = volumes[sfx];

        if (sfx == Sfx.Coin)
        {
            // Collecting coins quickly makes the pitch climb a little
            coinSource.pitch = coinPitch;
            coinSource.PlayOneShot(clip, volume);
            coinPitch = Mathf.Min(1.6f, coinPitch + 0.06f);
            lastCoinTime = Time.time;
            return;
        }

        sfxSource.PlayOneShot(clip, volume);
    }

    private AudioSource CreateSource(bool loop)
    {
        AudioSource source = gameObject.AddComponent<AudioSource>();
        source.playOnAwake = false;
        source.loop = loop;
        source.spatialBlend = 0f;
        return source;
    }

    private void ApplyMute()
    {
        AudioListener.volume = muted ? 0f : 1f;
    }

    // ---------- Sound effects ----------

    private void BuildSounds()
    {
        // Jump: quick upward sweep
        float[] jump = new float[Samples(0.25f)];
        AddTone(jump, 0f, 0.22f, 320f, 740f, 0.55f, Wave.Sine, 1.2f);
        Register(Sfx.Jump, jump, 0.7f);

        // Slide: soft whoosh
        float[] slide = new float[Samples(0.32f)];
        AddNoise(slide, 0f, 0.28f, 1.4f, 1.0f, 0.85f);
        Register(Sfx.Slide, slide, 0.6f);

        // Lane change: tiny tick
        float[] lane = new float[Samples(0.12f)];
        AddTone(lane, 0f, 0.08f, 520f, 380f, 0.3f, Wave.Triangle, 1.5f);
        Register(Sfx.Lane, lane, 0.5f);

        // Coin: two bright notes
        float[] coin = new float[Samples(0.35f)];
        AddTone(coin, 0f, 0.09f, 988f, 988f, 0.22f, Wave.Square, 1.2f);
        AddTone(coin, 0.07f, 0.24f, 1319f, 1319f, 0.22f, Wave.Square, 1.6f);
        Register(Sfx.Coin, coin, 0.6f);

        // Power-up: rising four-note run
        float[] powerUp = new float[Samples(0.55f)];
        float[] powerUpNotes = { 523.25f, 659.25f, 783.99f, 1046.5f };
        for (int i = 0; i < powerUpNotes.Length; i++)
        {
            AddTone(powerUp, i * 0.07f, 0.2f, powerUpNotes[i], powerUpNotes[i], 0.3f, Wave.Triangle, 1.5f);
        }
        Register(Sfx.PowerUp, powerUp, 0.8f);

        // Hit: low thud with a burst of noise
        float[] hit = new float[Samples(0.45f)];
        AddTone(hit, 0f, 0.35f, 160f, 45f, 0.9f, Wave.Sine, 1.5f);
        AddNoise(hit, 0f, 0.15f, 0.9f, 2f, 0.6f);
        Register(Sfx.Hit, hit, 1f);

        // Shield break: falling glassy sweep
        float[] shieldBreak = new float[Samples(0.4f)];
        AddTone(shieldBreak, 0f, 0.3f, 1100f, 250f, 0.35f, Wave.Square, 1.5f);
        AddNoise(shieldBreak, 0f, 0.12f, 0.6f, 2f, 0.3f);
        Register(Sfx.ShieldBreak, shieldBreak, 0.8f);

        // Game over: four falling notes plus a thud
        float[] gameOver = new float[Samples(1.4f)];
        float[] gameOverNotes = { 392f, 329.63f, 261.63f, 196f };
        for (int i = 0; i < gameOverNotes.Length; i++)
        {
            AddTone(gameOver, i * 0.22f, 0.5f, gameOverNotes[i], gameOverNotes[i], 0.45f, Wave.Triangle, 1.2f);
        }
        AddTone(gameOver, 0f, 0.3f, 120f, 50f, 0.6f, Wave.Sine, 1.5f);
        Register(Sfx.GameOver, gameOver, 0.9f);

        // Menu click
        float[] click = new float[Samples(0.1f)];
        AddTone(click, 0f, 0.06f, 900f, 700f, 0.3f, Wave.Square, 1.5f);
        Register(Sfx.Click, click, 0.6f);
    }

    private void Register(Sfx sfx, float[] data, float volume)
    {
        for (int i = 0; i < data.Length; i++)
        {
            data[i] = Mathf.Clamp(data[i], -1f, 1f);
        }

        AudioClip clip = AudioClip.Create(sfx.ToString(), data.Length, 1, SampleRate, false);
        clip.SetData(data, 0);

        clips[sfx] = clip;
        volumes[sfx] = volume;
    }

    // ---------- Music ----------

    private AudioClip BuildMusic()
    {
        const float bpm = 124f;
        const int stepsPerBar = 8;
        const int bars = 4;

        float eighth = 60f / bpm / 2f;
        int totalSteps = stepsPerBar * bars;
        float[] buffer = new float[Samples(totalSteps * eighth)];

        // Chord progression: Am, F, C, G
        float[] bassNotes = { 110f, 87.31f, 130.81f, 98f };
        float[][] chords =
        {
            new float[] { 440f, 523.25f, 659.25f },
            new float[] { 349.23f, 440f, 523.25f },
            new float[] { 523.25f, 659.25f, 783.99f },
            new float[] { 392f, 493.88f, 587.33f }
        };
        int[] arpeggio = { 0, 1, 2, 1, 0, 1, 2, 1 };

        for (int step = 0; step < totalSteps; step++)
        {
            int bar = step / stepsPerBar;
            int stepInBar = step % stepsPerBar;
            float time = step * eighth;

            // Arpeggio pluck on every step
            float noteFrequency = chords[bar][arpeggio[stepInBar]];
            AddTone(buffer, time, eighth * 1.6f, noteFrequency, noteFrequency, 0.10f, Wave.Triangle, 2f);

            // Bass on every beat
            if (stepInBar % 2 == 0)
            {
                AddTone(buffer, time, eighth * 1.9f, bassNotes[bar], bassNotes[bar], 0.30f, Wave.Triangle, 1.5f);
            }

            // Kick twice per bar
            if (stepInBar % 4 == 0)
            {
                AddTone(buffer, time, 0.14f, 140f, 45f, 0.35f, Wave.Sine, 2f);
            }

            // Soft hi-hat between the beats
            if (stepInBar % 2 == 1)
            {
                AddNoise(buffer, time, 0.04f, 0.06f, 2f, 0f);
            }
        }

        for (int i = 0; i < buffer.Length; i++)
        {
            buffer[i] = Mathf.Clamp(buffer[i], -1f, 1f);
        }

        AudioClip music = AudioClip.Create("Music", buffer.Length, 1, SampleRate, false);
        music.SetData(buffer, 0);
        return music;
    }

    // ---------- Sound building blocks ----------

    private static int Samples(float seconds)
    {
        return Mathf.RoundToInt(seconds * SampleRate);
    }

    private static float Oscillator(Wave wave, float phase)
    {
        phase -= Mathf.Floor(phase);

        switch (wave)
        {
            case Wave.Square:
                return phase < 0.5f ? 0.6f : -0.6f;
            case Wave.Triangle:
                return 1f - 4f * Mathf.Abs(phase - 0.5f);
            default:
                return Mathf.Sin(phase * 2f * Mathf.PI);
        }
    }

    // Adds a tone that can glide from one pitch to another. It wraps around the end of the
    // buffer, which keeps the music loop seamless.
    private static void AddTone(float[] buffer, float startTime, float duration,
        float startFrequency, float endFrequency, float volume, Wave wave, float decayPower)
    {
        int start = Samples(startTime);
        int count = Samples(duration);
        float phase = 0f;

        for (int i = 0; i < count; i++)
        {
            int index = (start + i) % buffer.Length;
            float t = (float)i / count;

            float frequency = Mathf.Lerp(startFrequency, endFrequency, t);
            phase += frequency / SampleRate;

            float attack = Mathf.Min(1f, i / (SampleRate * 0.004f));
            float envelope = attack * Mathf.Pow(1f - t, decayPower);

            buffer[index] += Oscillator(wave, phase) * envelope * volume;
        }
    }

    // Adds noise. Higher smoothing (up to about 0.9) makes it softer and darker.
    private static void AddNoise(float[] buffer, float startTime, float duration,
        float volume, float decayPower, float smoothing)
    {
        int start = Samples(startTime);
        int count = Samples(duration);
        float last = 0f;

        for (int i = 0; i < count; i++)
        {
            int index = (start + i) % buffer.Length;
            float t = (float)i / count;

            float white = (float)(noiseGenerator.NextDouble() * 2.0 - 1.0);
            last = last * smoothing + white * (1f - smoothing);

            float attack = Mathf.Min(1f, i / (SampleRate * 0.004f));
            float envelope = attack * Mathf.Pow(1f - t, decayPower);

            buffer[index] += last * envelope * volume;
        }
    }

    // ---------- Sound on/off button (menu only) ----------

    void OnGUI()
    {
        GameManager gm = GameManager.Instance;
        if (gm == null || gm.State != GameState.Menu) return;

        float unit = Mathf.Max(Mathf.Min(Screen.height / 20f, Screen.width / 16f), 12f);

        GUIStyle style = new GUIStyle(GUI.skin.button);
        style.fontSize = Mathf.RoundToInt(unit * 0.7f);

        Rect rect = new Rect(Screen.width - unit * 7f, Screen.height - unit * 2.4f, unit * 6f, unit * 1.7f);

        if (GUI.Button(rect, muted ? "Sound: OFF" : "Sound: ON", style))
        {
            muted = !muted;
            PlayerPrefs.SetInt("Muted", muted ? 1 : 0);
            PlayerPrefs.Save();
            ApplyMute();

            if (!muted) PlayInternal(Sfx.Click);
        }
    }
}